window.addEventListener('keyup',e=>{keys[e.code]=false});
canvas.addEventListener('pointerdown',e=>{if(!running)return;canvas.setPointerCapture?.(e.pointerId);const p=point(e);if(touchMode){if(p.x<300&&p.y>VIEW_H*.54){joystick={id:e.pointerId,x:p.x,y:p.y};moveX=moveY=0}else if(p.x>W*.75&&p.y>VIEW_H*.54){lookPointer={id:e.pointerId,x:p.x,y:p.y};tryFire()}else lookPointer={id:e.pointerId,x:p.x,y:p.y}}else tryFire()});
